// Room identity is painted into the cached floor; particles stay inexpensive and local.
const CITADEL_THEMES=[{name:'Sığınak',wash:'#769b8030',accent:'#c5c79b'},{name:'Demir',wash:'#ad77411c',accent:'#d6a15f'},{name:'Kül toprağı',wash:'#a28a5124',accent:'#c7b477'},{name:'Sarnıç',wash:'#4b9b8830',accent:'#83c3b1'},{name:'Zincir',wash:'#8c83a224',accent:'#c7b6d0'},{name:'Kütüphane',wash:'#b5604920',accent:'#e2ab73'},{name:'Kışla',wash:'#8e4a5a22',accent:'#d0a49d'},{name:'Taht',wash:'#ba773123',accent:'#efc482'}];
const floorBeforeCitadel=makeDungeonFloor;makeDungeonFloor=function(){floorBeforeCitadel();DUNGEON.rooms.forEach((r,n)=>{const chunk=dungeonFloor[n],g=chunk.c.getContext('2d'),theme=CITADEL_THEMES[n];g.save();g.setTransform(1,0,0,1,0,0);g.translate(30,54);g.fillStyle=theme.wash;g.fillRect(1,1,r.w-2,r.h-2);g.strokeStyle=theme.accent+'45';g.lineWidth=3;g.strokeRect(54,54,r.w-108,r.h-108);
 if([1,4,6].includes(n)){for(const y of [r.h*.22,r.h*.78]){g.fillStyle='#121f2c55';g.fillRect(70,y,r.w-140,35);g.fillStyle=theme.accent+'55';for(let x=80;x<r.w-70;x+=30)g.fillRect(x,y+4,7,27)}}
 if(n===2){for(let j=0;j<46;j++){const x=80+(j*173)%(r.w-160),y=110+(j*271)%(r.h-220);g.fillStyle=j%3?'#7b80662f':'#c6bb8b33';g.fillRect(x,y,10+j%4*5,4)}}
 if(n===3){for(const side of [0,1]){g.fillStyle='#163d4055';g.fillRect(side?r.w-100:70,140,30,r.h-280);g.fillStyle='#94b8a566';for(let y=150;y<r.h-140;y+=54)g.fillRect(side?r.w-99:71,y,28,5)}}
 if(n===4){const x=r.w/2,y=r.h/2;g.strokeStyle='#b8a7c154';g.lineWidth=3;for(const radius of [90,135,160]){g.beginPath();g.arc(x,y,radius,0,7);g.stroke()}g.beginPath();for(let j=0;j<=6;j++){const angle=j*Math.PI*2/3-Math.PI/2;j?g.lineTo(x+Math.cos(angle)*130,y+Math.sin(angle)*130):g.moveTo(x+Math.cos(angle)*130,y+Math.sin(angle)*130)}g.stroke()}
 if(n===5){g.fillStyle='#78604b24';g.fillRect(65,135,170,r.h-270);g.fillRect(r.w-235,135,170,r.h-270);for(let j=0;j<30;j++){const x=90+(j*157)%(r.w-180),y=170+(j*199)%(r.h-340);g.save();g.translate(x,y);g.rotate(j*.7);g.fillStyle=j%2?'#b9a98066':'#817d7166';g.fillRect(0,0,12,17);g.fillStyle='#4c4b4777';g.fillRect(3,4,7,2);g.fillRect(3,8,7,2);g.restore()}}
 if(n===7){g.strokeStyle='#c3865044';g.lineWidth=4;for(let j=0;j<10;j++){const a=j*Math.PI*.2,x=r.w/2,y=r.h*.43;g.beginPath();g.moveTo(x+Math.cos(a)*180,y+Math.sin(a)*180);g.lineTo(x+Math.cos(a+.08)*235,y+Math.sin(a+.08)*235);g.lineTo(x+Math.cos(a-.05)*300,y+Math.sin(a-.05)*300);g.stroke()}}
 g.restore()})};
const furnitureBeforeAtmosphere=drawDungeonFurniture;drawDungeonFurniture=function(r,n){furnitureBeforeAtmosphere(r,n);const accent=CITADEL_THEMES[n].accent;if([1,4,6,7].includes(n)){for(const side of [0,1]){const x=r.x+(side?r.w-220:220),y=r.y+100;ctx.save();ctx.strokeStyle='#879082';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,y-40);for(let j=0;j<7;j++)ctx.lineTo(x+Math.sin(j*1.8)*5,y-30+j*14);ctx.stroke();ctx.strokeStyle=accent;ctx.lineWidth=2;for(let j=0;j<5;j++)ctx.strokeRect(x-4,y-25+j*13,8,12);ctx.restore()}}
 if(n===5){for(const side of [0,1])for(let j=0;j<3;j++){const x=r.x+(side?r.w-115:115),y=r.y+600+j*130;rect(x-35,y-55,70,60,'#1d2a34');rect(x-32,y-52,64,52,'#64513f');rect(x-28,y-45,56,3,'#ac9370');for(let k=0;k<5;k++)rect(x-25+k*11,y-36,8,25,['#8b7860','#85766f','#798e7d'][k%3]);rect(x-33,y-8,66,7,'#a58a64')}}
 if(n===6){for(const side of [0,1]){const x=r.x+(side?r.w-220:220),y=r.y+r.h-230;rect(x-32,y-13,64,17,'#5d6f72');polygon([[x-17,y-14],[x-23,y-46],[x-5,y-75],[x+17,y-60],[x+25,y-28],[x+11,y-15]],'#3d535d');polygon([[x-15,y-42],[x-4,y-66],[x+11,y-55],[x+16,y-31]],'#87978f');rect(x-7,y-91,19,23,'#99a296');rect(x-4,y-85,5,5,'#334952');rect(x+5,y-85,4,5,'#334952');rect(x-3,y-74,11,3,'#566d70')}}
 if(n===7){for(const side of [0,1]){const x=r.x+(side?r.w-170:170),y=r.y+420;rect(x-42,y-18,84,25,'#53656d');rect(x-30,y-95,60,77,'#324b5a');rect(x-22,y-88,16,59,'#778e8c');polygon([[x-35,y-97],[x-40,y-129],[x-20,y-145],[x+20,y-145],[x+41,y-129],[x+35,y-97]],'#5b7478');rect(x-18,y-134,36,16,'#9aab9d');rect(x-13,y-128,9,4,'#e1b877');rect(x+5,y-128,9,4,'#e1b877');rect(x-4,y-114,8,12,'#a6b6a7')}}
 ctx.save();for(let j=0;j<13;j++){const x=r.x+70+(j*197)%(r.w-140),y=r.y+100+((j*281+time*(n===3?9:4))%(r.h-200));ctx.globalAlpha=.1+(Math.sin(time+j)+1)*.06;rect(x,y,n===3?3:2,n===3?3:2,accent)}ctx.restore();
};
dungeonFloor=null;
